INSERT INTO authors (id, name, slug, designation, bio) VALUES
  (1, 'Aditi Rao', 'aditi-rao', 'Senior Correspondent', 'Aditi reports on grassroots changemakers across central and eastern India. She has spent a decade travelling by train to stories most people never hear about.'),
  (2, 'Kabir Sethi', 'kabir-sethi', 'Environment Editor', 'Kabir covers water, forests and climate adaptation. He is happiest knee-deep in a restored wetland with a notebook.'),
  (3, 'Meera Pillai', 'meera-pillai', 'Features Writer', 'Meera writes about culture, food and the crafts that are quietly being rescued by a new generation.'),
  (4, 'Arjun Deshmukh', 'arjun-deshmukh', 'Innovation Reporter', 'Arjun tracks frugal engineering, small-town startups and the tinkerers who build what they cannot buy.');
INSERT INTO categories (id, name, slug, description, color, sort_order, show_on_home) VALUES
  (1, 'Changemakers', 'changemakers', 'People quietly fixing problems in their own neighbourhoods.', '#B4232A', 1, 1),
  (2, 'Environment', 'environment', 'Water, forests, waste and climate, told through the people working on them.', '#2F6B4F', 2, 1),
  (3, 'Innovation', 'innovation', 'Frugal engineering and homegrown ideas that solve real problems.', '#2E5AAC', 3, 1),
  (4, 'Rural India', 'rural-india', 'Farms, villages and the economies that keep them going.', '#8C5A33', 4, 1),
  (5, 'Culture & Heritage', 'culture-heritage', 'Crafts, monuments, food and the people keeping traditions alive.', '#8E3B5E', 5, 1),
  (6, 'Health', 'health', 'Care that reaches people where they live.', '#1F7A7A', 6, 1),
  (7, 'Education', 'education', 'Classrooms, libraries and second chances.', '#B06A10', 7, 1),
  (8, 'Travel', 'travel', 'Places worth the journey, and the communities that host you.', '#3D5A80', 8, 1);
