INSERT INTO media (id, type, storage, url, original_name, mime_type, width, height, alt_text, uploaded_by) VALUES
  (1, 'image', 'local', '/uploads/seed/postman-library.jpg', 'postman-library.jpg', 'image/jpeg', 1600, 1000, 'Bhagaban covers roughly 40 km a day on the same route he walked as a postman.', 1),
  (2, 'image', 'local', '/uploads/seed/gallery-1.jpg', 'gallery-1.jpg', 'image/jpeg', 1600, 1000, 'The lending register Bhagaban keeps in a school notebook.', 1),
  (3, 'image', 'local', '/uploads/seed/gallery-3.jpg', 'gallery-3.jpg', 'image/jpeg', 1600, 1000, 'The road to Kantapada, the farthest village on his route.', 1),
  (4, 'image', 'local', '/uploads/seed/kutch-lake.jpg', 'kutch-lake.jpg', 'image/jpeg', 1600, 1000, 'The restored lake held water through the summer for the first time in 19 years.', 1),
  (5, 'image', 'local', '/uploads/seed/soil-sensor.jpg', 'soil-sensor.jpg', 'image/jpeg', 1600, 1000, 'The probe sits 30 cm deep and sends one message a day.', 1),
  (6, 'image', 'local', '/uploads/seed/bell-metal.jpg', 'bell-metal.jpg', 'image/jpeg', 1600, 1000, 'A workshop in lower Assam, where bell-metal plates are still hammered by hand.', 1),
  (7, 'image', 'local', '/uploads/seed/night-school.jpg', 'night-school.jpg', 'image/jpeg', 1600, 1000, 'Classes begin at 10:30 pm, after the dinner peak.', 1),
  (8, 'image', 'local', '/uploads/seed/mizoram-homestay.jpg', 'mizoram-homestay.jpg', 'image/jpeg', 1600, 1000, 'The homestay sits on a ridge an hour from Aizawl.', 1),
  (9, 'image', 'local', '/uploads/seed/eye-camp.jpg', 'eye-camp.jpg', 'image/jpeg', 1600, 1000, 'Patients begin queuing before sunrise outside the village school.', 1),
  (10, 'image', 'local', '/uploads/seed/seed-library.jpg', 'seed-library.jpg', 'image/jpeg', 1600, 1000, 'Seeds are stored in clay pots sealed with neem leaves.', 1),
  (11, 'image', 'local', '/uploads/seed/plastic-shelter.jpg', 'plastic-shelter.jpg', 'image/jpeg', 1600, 1000, 'Each eco-brick is a bottle packed tight with soft plastic waste.', 1),
  (12, 'image', 'local', '/uploads/seed/railway-app.jpg', 'railway-app.jpg', 'image/jpeg', 1600, 1000, 'The app works offline once a station’s audio model is downloaded.', 1),
  (13, 'image', 'local', '/uploads/seed/solar-cooperative.jpg', 'solar-cooperative.jpg', 'image/jpeg', 1600, 1000, 'Members carry a standard toolkit and a logbook for every repair.', 1),
  (14, 'image', 'local', '/uploads/seed/kerala-beach.jpg', 'kerala-beach.jpg', 'image/jpeg', 1600, 1000, 'Fishing boats now return with nets of plastic as well as fish.', 1),
  (15, 'image', 'local', '/uploads/seed/stepwell.jpg', 'stepwell.jpg', 'image/jpeg', 1600, 1000, 'The stepwell’s geometry is visible again after decades under debris.', 1),
  (16, 'image', 'local', '/uploads/seed/gallery-2.jpg', 'gallery-2.jpg', 'image/jpeg', 1600, 1000, 'Volunteers cleared the steps by hand, one landing at a time.', 1),
  (17, 'image', 'local', '/uploads/seed/pickle-enterprise.jpg', 'pickle-enterprise.jpg', 'image/jpeg', 1600, 1000, 'Pickles are sun-cured on rooftops for up to three weeks.', 1),
  (18, 'image', 'local', '/uploads/seed/mangrove.jpg', 'mangrove.jpg', 'image/jpeg', 1600, 1000, 'Saplings are raised in community nurseries before planting at low tide.', 1),
  (19, 'video', 'external', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', 'flower.mp4', 'video/mp4', NULL, NULL, 'Sample video', 1),
  (20, 'image', 'local', '/uploads/seed/ladakh-greenhouse.jpg', 'ladakh-greenhouse.jpg', 'image/jpeg', 1600, 1000, 'A greenhouse uses thick mud walls to store the day’s heat.', 1);
