SET NAMES utf8mb4;
SET time_zone = '+00:00';
START TRANSACTION;






  status, is_featured, is_editors_pick, video_type, video_url, video_media_id, reading_time, views,
  meta_title, meta_description, published_at, created_by, updated_by) VALUES
  (1, 'A retired postman in Odisha has delivered 4,000 library books by bicycle', 'a-retired-postman-in-odisha-has-delivered-4000-library-books-by-bicycle', 'After 34 years on the same route, Bhagaban Mallick swapped letters for library books. His canvas bag now carries novels, textbooks and newspapers to eleven villages.', '<p>Every morning at seven, Bhagaban Mallick ties a canvas bag to the carrier of his bicycle and checks the register one more time. Thirty-one books today. Four are overdue, and he already knows which doorsteps to stop at first.</p>\n<p>For 34 years, Bhagaban delivered letters on this same route through the villages around Kantapada. When he retired in 2021, he found that he could not stop. \"People still waited for me at the gate,\" he says. \"Only now, nobody was writing letters.\"</p>\n<h2>From letters to libraries</h2>\n<p>He began with 60 books from his own shelf and a few donated by the school where his daughter teaches. Within a year, word had spread. Teachers, retired officers and a bookshop in Cuttack began sending cartons. Today his lending library has a little over 1,200 titles and a waiting list for the Odia translation of a popular detective series.</p>\n<blockquote><p>A letter used to bring news from far away. A book does the same thing, only it lasts longer.</p></blockquote>\n<p>Borrowing is free. The only rule is that every book must come back in the condition it left. Children who return books on time get to choose first from the new carton, a privilege that has done more for punctuality than any fine.</p>\n<h2>What the numbers say</h2>\n<p>Bhagaban has logged 4,000 deliveries in a set of school notebooks. The most borrowed category is not fiction but exam guides, which he now buys with small contributions from parents. Teachers at the local high school say reading scores have quietly improved, though nobody has studied it formally.</p>\n<p>He has no plans to stop. \"My knees will tell me when,\" he laughs, and pedals off towards the next village.</p>', 1, 'Bhagaban covers roughly 40 km a day on the same route he walked as a postman.', 1, 1, 'published', 1, 1, 'none', NULL, NULL, 2, 18420, 'A retired postman in Odisha has delivered 4,000 library books by bicycle', 'After 34 years on the same route, Bhagaban Mallick swapped letters for library books. His canvas bag now carries novels, textbooks and newspapers to eleven villages.', UTC_TIMESTAMP() - INTERVAL 3 HOUR, 1, 1),
  (2, 'How a Kutch village turned a dry lake into a year-round water bank', 'how-a-kutch-village-turned-a-dry-lake-into-a-year-round-water-bank', 'Desilting, a ring of check dams and a strict village rulebook brought back a lake that had been dry for most of the last two decades.', '<p>For most of the last twenty years, the lake at the edge of Navagam was a cracked bowl of clay that filled for a few weeks after the monsoon and vanished by Diwali. Women walked three kilometres for drinking water. Young men left for the salt pans.</p>\n<p>In 2022, the village council decided to try something old. With the help of a local water collective, residents mapped the catchment on foot, identified seven blocked inlet channels and spent two dry seasons removing 18,000 tractor loads of silt.</p>\n<h2>A rulebook written by the village</h2>\n<p>Restoring the lake was only half the work. The gram sabha agreed on rules that every household signed: no borewells within 500 metres of the shore, no pumping for irrigation after February, and a rotating committee to guard the inlets during the rains.</p>\n<blockquote><p>We did not build anything new. We only undid the damage and agreed to share.</p></blockquote>\n<p>The silt itself became an asset. Farmers spread it on their fields, and several report better yields of cumin and castor. This summer, the lake held water until the monsoon arrived for the first time in 19 years.</p>\n<p>Neighbouring villages have started visiting with notebooks. The council has a simple answer for all of them: start with the map, not the machines.</p>', 4, 'The restored lake held water through the summer for the first time in 19 years.', 2, 2, 'published', 1, 0, 'none', NULL, NULL, 2, 12950, 'How a Kutch village turned a dry lake into a year-round water bank', 'Desilting, a ring of check dams and a strict village rulebook brought back a lake that had been dry for most of the last two decades.', UTC_TIMESTAMP() - INTERVAL 7 HOUR, 1, 1),
  (3, 'Two Pune engineers built a ₹900 sensor that tells farmers exactly when to irrigate', 'two-pune-engineers-built-a-900-sensor-that-tells-farmers-exactly-when-to-irrigate', 'A soil-moisture probe made from off-the-shelf parts sends a single SMS when a field needs water, and farmers using it report using about a third less.', '<p>Shreya Kulkarni and Rohan Bhide met in a college robotics club and kept tinkering long after graduation. Their latest project is a sensor the size of a pen, powered by a coin cell, that does one thing: it tells a farmer when the soil at root depth is actually dry.</p>\n<p>\"Most farmers irrigate by calendar or by looking at the topsoil,\" Shreya explains. \"The top two inches dry fast. The roots are often still fine.\"</p>\n<h2>Deliberately simple</h2>\n<p>There is no app and no dashboard. When moisture drops below a threshold set for the crop, the farmer gets one SMS in Marathi. The device costs ₹900 to make and runs for a full season on its battery.</p>\n<p>In a pilot across 120 farms near Baramati, growers using the sensor pumped about 30 percent less water with no drop in yield. Electricity bills fell too, a detail farmers mentioned far more often than water.</p>\n<blockquote><p>We kept removing features until it was something a busy farmer would never have to think about.</p></blockquote>\n<p>The pair have open-sourced the hardware design and are working with two farmer producer organisations to manufacture the next 5,000 units locally.</p>', 5, 'The probe sits 30 cm deep and sends one message a day.', 3, 4, 'published', 1, 1, 'none', NULL, NULL, 1, 9870, 'Two Pune engineers built a ₹900 sensor that tells farmers exactly when to irrigate', 'A soil-moisture probe made from off-the-shelf parts sends a single SMS when a field needs water, and farmers using it report using about a third less.', UTC_TIMESTAMP() - INTERVAL 11 HOUR, 1, 1),
  (4, 'The last bell-metal craftsmen of an Assam village are training their daughters', 'the-last-bell-metal-craftsmen-of-an-assam-village-are-training-their-daughters', 'For generations the craft passed only from father to son. With fewer sons staying, master artisans are rewriting the rule.', '<p>The sound reaches you before the workshop does: a steady, ringing rhythm of hammers on hot bell metal. Inside, Jonali Das, 22, is shaping a plate that will take her three days to finish.</p>\n<p>Until recently, she would not have been allowed to touch the hammer. In her village, the craft of making kanh, the traditional bell-metal utensils of Assam, was passed down only from father to son.</p>\n<h2>A rule that no longer worked</h2>\n<p>Her father, Haren Das, has worked metal for 41 years. Both his sons now work in Guwahati. \"I had two choices,\" he says. \"Let the craft end with me, or teach whoever wanted to learn.\"</p>\n<p>Today eleven young women train in four family workshops. They have also brought something new: an Instagram page, custom engraving and a waiting list of buyers from Bengaluru and Pune.</p>\n<blockquote><p>The metal does not know who is holding the hammer.</p></blockquote>\n<p>Prices for a hand-hammered plate have risen by almost half in two years, enough that two of the brothers are thinking about coming home.</p>', 6, 'A workshop in lower Assam, where bell-metal plates are still hammered by hand.', 5, 3, 'published', 1, 0, 'none', NULL, NULL, 1, 7420, 'The last bell-metal craftsmen of an Assam village are training their daughters', 'For generations the craft passed only from father to son. With fewer sons staying, master artisans are rewriting the rule.', UTC_TIMESTAMP() - INTERVAL 20 HOUR, 1, 1),
  (5, 'Inside the night school where Bengaluru’s delivery riders learn English', 'inside-the-night-school-where-bengalurus-delivery-riders-learn-english', 'Between the dinner rush and the late-night orders, riders gather in a borrowed classroom for ninety minutes of conversation practice.', '<p>At 10:30 pm, a classroom in a government school in Koramangala fills with helmets. Twenty-six delivery riders take their seats, phones face down, for ninety minutes of English conversation.</p>\n<p>The night school was started by Farhan Qureshi, a former rider who now manages a fleet. \"Customers would complain, and riders could not explain what happened,\" he says. \"Not because they were wrong. Because they did not have the words.\"</p>\n<h2>Lessons built from real conversations</h2>\n<p>The syllabus is practical: explaining a delay, asking for directions, handling a wrong address, negotiating with a building guard. Volunteers from nearby offices teach in pairs, and every lesson ends with role play.</p>\n<p>Riders say ratings have improved, but the bigger change is confidence. Several have used their new skills in interviews for warehouse supervisor and customer-support roles.</p>\n<blockquote><p>The first thing I learned to say was \"please wait two minutes\". Now I can explain anything.</p></blockquote>\n<p>The school runs on donated tea and borrowed chalk. A second batch starts in Indiranagar next month.</p>', 7, 'Classes begin at 10:30 pm, after the dinner peak.', 7, 1, 'published', 0, 0, 'none', NULL, NULL, 1, 6210, 'Inside the night school where Bengaluru’s delivery riders learn English', 'Between the dinner rush and the late-night orders, riders gather in a borrowed classroom for ninety minutes of conversation practice.', UTC_TIMESTAMP() - INTERVAL 26 HOUR, 1, 1),
  (6, 'A Mizoram homestay that runs entirely on rainwater and sunshine', 'a-mizoram-homestay-that-runs-entirely-on-rainwater-and-sunshine', 'Five rooms, a 40,000-litre rain tank and a rooftop solar array: how one family built a guesthouse that has never needed the grid.', '<p>The road to Lalrinpuii’s homestay ends in a bamboo gate and a view that stretches across three ridges. Her family opened five rooms to travellers in 2020, with one condition: the guesthouse would never draw from the grid or the village spring.</p>\n<p>Every roof slopes towards a 40,000-litre underground tank. A rooftop solar array and a battery bank power lights, fans and a water heater. Food comes from the family’s own terraced garden and neighbours’ farms.</p>\n<h2>Guests become part of the routine</h2>\n<p>Visitors are asked to take bucket baths during dry months and to switch off lights during cloudy spells. Almost nobody complains. Several return guests now arrive with seeds from their own gardens.</p>\n<p>The homestay employs four young people from the village and buys from fourteen households. Lalrinpuii says the business model is simple: \"Spend less on things, and more on people.\"</p>', 8, 'The homestay sits on a ridge an hour from Aizawl.', 8, 3, 'published', 0, 0, 'none', NULL, NULL, 1, 5480, 'A Mizoram homestay that runs entirely on rainwater and sunshine', 'Five rooms, a 40,000-litre rain tank and a rooftop solar array: how one family built a guesthouse that has never needed the grid.', UTC_TIMESTAMP() - INTERVAL 33 HOUR, 1, 1),
  (7, 'This doctor couple runs a free eye camp every Sunday in tribal Jharkhand', 'this-doctor-couple-runs-a-free-eye-camp-every-sunday-in-tribal-jharkhand', 'In nine years, Dr Nandini and Dr Prakash Murmu have screened more than 60,000 people and arranged over 7,000 cataract surgeries.', '<p>By six on a Sunday morning, the queue outside the primary school already curves around the playground. Some patients have walked from villages twelve kilometres away.</p>\n<p>Inside, Dr Nandini Murmu and her husband Dr Prakash Murmu set up an eye-testing station on two school desks. They have done this almost every Sunday for nine years.</p>\n<h2>Cataract is the biggest enemy</h2>\n<p>Most patients have cataracts that went untreated for years, slowly turning daily work into guesswork. The couple screen, prescribe glasses on the spot and book surgeries at a partner hospital in Ranchi, with free transport both ways.</p>\n<blockquote><p>When a grandmother can see her grandchild’s face again, she does not say thank you. She just holds your hand.</p></blockquote>\n<p>They have trained 22 local health workers to do basic vision screening, so the camp can now focus on people who need a doctor most.</p>', 9, 'Patients begin queuing before sunrise outside the village school.', 6, 1, 'published', 0, 1, 'none', NULL, NULL, 1, 8830, 'This doctor couple runs a free eye camp every Sunday in tribal Jharkhand', 'In nine years, Dr Nandini and Dr Prakash Murmu have screened more than 60,000 people and arranged over 7,000 cataract surgeries.', UTC_TIMESTAMP() - INTERVAL 40 HOUR, 1, 1),
  (8, 'The seed library keeping 300 heirloom rice varieties alive', 'the-seed-library-keeping-300-heirloom-rice-varieties-alive', 'Farmers borrow a kilo of seed and return two after harvest. A simple rule has saved varieties that had nearly disappeared.', '<p>In a mud-walled room in a village in West Bengal, 312 clay pots line the shelves. Each holds a different variety of rice, some with names that only a handful of elderly farmers still remember.</p>\n<p>The seed library works like any other: farmers borrow a kilo and return two after harvest. The extra seed goes to the next borrower.</p>\n<h2>Flavour, resilience and memory</h2>\n<p>Several varieties tolerate salt water or flooding better than modern hybrids, which has made them newly valuable after recent cyclones. Others are prized for aroma or for the festival dishes they are traditionally used in.</p>\n<p>Young farmers now record every variety’s behaviour in a shared notebook: days to harvest, height, yield and taste. It is slowly becoming a field guide that no laboratory could have written.</p>', 10, 'Seeds are stored in clay pots sealed with neem leaves.', 4, 2, 'published', 0, 0, 'none', NULL, NULL, 1, 4310, 'The seed library keeping 300 heirloom rice varieties alive', 'Farmers borrow a kilo of seed and return two after harvest. A simple rule has saved varieties that had nearly disappeared.', UTC_TIMESTAMP() - INTERVAL 52 HOUR, 1, 1),
  (9, 'Students in Nagaland built a bus shelter from 12,000 plastic bottles', 'students-in-nagaland-built-a-bus-shelter-from-12000-plastic-bottles', 'A class project turned into a village landmark, and a plan to clear plastic from the river that runs below the school.', '<p>It started as a Class 9 science project on plastic pollution. Six months later, the students of a government school in Nagaland had collected 12,000 bottles from the riverbank and packed each one tight with chip packets and wrappers.</p>\n<p>The resulting eco-bricks, set in mud mortar and plastered with lime, now form a bus shelter at the village junction. It has survived two monsoons.</p>\n<p>The students have since mapped every plastic hotspot along a two-kilometre stretch of the river and run a monthly clean-up with the village youth club.</p>', 11, 'Each eco-brick is a bottle packed tight with soft plastic waste.', 2, 2, 'published', 0, 0, 'none', NULL, NULL, 1, 3920, 'Students in Nagaland built a bus shelter from 12,000 plastic bottles', 'A class project turned into a village landmark, and a plan to clear plastic from the river that runs below the school.', UTC_TIMESTAMP() - INTERVAL 60 HOUR, 1, 1),
  (10, 'An app built in Indore turns railway announcements into text for deaf passengers', 'an-app-built-in-indore-turns-railway-announcements-into-text-for-deaf-passengers', 'Listening to platform speakers in real time, the free app shows train numbers, platform changes and delays as large, clear text.', '<p>Platform announcements are a lifeline for most passengers and a wall of noise for people who are deaf or hard of hearing. Tanvi Jain, a final-year computer science student in Indore, grew up watching her cousin miss train after train because of a last-minute platform change.</p>\n<p>Her app listens through the phone’s microphone, recognises announcements in Hindi and English, and shows the key details in large text: train number, platform, expected time.</p>\n<h2>Tested on the platforms it was built for</h2>\n<p>Tanvi and two classmates spent months recording announcements at Indore Junction to train the recognition model on real platform acoustics, echoes and all. The app now works offline and supports 14 major stations.</p>\n<blockquote><p>It should not take a stranger’s kindness to know which platform your train is on.</p></blockquote>\n<p>More than 20,000 people have downloaded it. The team is working with a deaf community organisation to add Indian Sign Language video for the most common announcements.</p>', 12, 'The app works offline once a station’s audio model is downloaded.', 3, 4, 'published', 1, 0, 'none', NULL, NULL, 1, 11240, 'An app built in Indore turns railway announcements into text for deaf passengers', 'Listening to platform speakers in real time, the free app shows train numbers, platform changes and delays as large, clear text.', UTC_TIMESTAMP() - INTERVAL 14 HOUR, 1, 1),
  (11, 'Meet the women running Madhya Pradesh’s first all-women solar repair cooperative', 'meet-the-women-running-madhya-pradeshs-first-all-women-solar-repair-cooperative', 'Forty women who once could not get a technician to visit now fix solar pumps, lights and inverters across 60 villages.', '<p>When a solar pump broke in their village, it used to stay broken for weeks. Technicians came from the district town, if they came at all. So in 2023, a self-help group of women in Madhya Pradesh asked a simple question: why can’t we fix it ourselves?</p>\n<p>Today their cooperative has 40 trained members who repair solar pumps, home lighting systems and inverters across 60 villages. They charge a fixed fee per visit and keep a shared stock of spare parts.</p>\n<h2>Skills that pay</h2>\n<p>Most members earn between ₹6,000 and ₹11,000 a month, often more than their husbands earn from farming in a dry season. Two members now train new technicians for a state rural livelihoods programme.</p>\n<blockquote><p>People used to ask where the technician was. Now they ask for me by name.</p></blockquote>', 13, 'Members carry a standard toolkit and a logbook for every repair.', 1, 1, 'published', 0, 1, 'none', NULL, NULL, 1, 7650, 'Meet the women running Madhya Pradesh’s first all-women solar repair cooperative', 'Forty women who once could not get a technician to visit now fix solar pumps, lights and inverters across 60 villages.', UTC_TIMESTAMP() - INTERVAL 72 HOUR, 1, 1),
  (12, 'Why one Kerala beach town has almost no plastic on its shore', 'why-one-kerala-beach-town-has-almost-no-plastic-on-its-shore', 'A deposit on every bottle, fishermen paid to bring back plastic from the sea, and a town that decided not to wait for a rule.', '<p>Walk the beach at dawn in this small fishing town in Kerala and you will find footprints, crab holes and very little else. Five years ago, plastic washed up in drifts.</p>\n<p>The change came from the fishing community. The panchayat now pays boats a small fee for every kilo of plastic they bring back from sea, and shops charge a ₹5 deposit on every bottle sold, refunded on return.</p>\n<p>Collected plastic is shredded at a unit run by a women’s collective and sold to a road-building contractor. The town has turned waste into a small but steady source of income.</p>', 14, 'Fishing boats now return with nets of plastic as well as fish.', 2, 2, 'published', 0, 0, 'none', NULL, NULL, 1, 5120, 'Why one Kerala beach town has almost no plastic on its shore', 'A deposit on every bottle, fishermen paid to bring back plastic from the sea, and a town that decided not to wait for a rule.', UTC_TIMESTAMP() - INTERVAL 90 HOUR, 1, 1),
  (13, 'Volunteers restored a 400-year-old stepwell in Rajasthan. Now it is full again', 'volunteers-restored-a-400-year-old-stepwell-in-rajasthan-now-it-is-full-again', 'Two years of weekend work by 300 volunteers cleared tonnes of debris and brought water back to a forgotten baori.', '<p>For decades, the stepwell at the edge of the old town was a dumping ground. Its carved steps disappeared under rubble, plastic and silt. Most residents under forty did not know it existed.</p>\n<p>In 2023, a group of college students started clearing it on weekends. Two years and 300 volunteers later, the baori’s eleven levels are visible again, and after a good monsoon it holds water to the sixth step.</p>\n<h2>Heritage that works</h2>\n<p>Stepwells were built to store rainwater through dry months. Once cleared, this one began recharging nearby wells, and families who had relied on tankers report that their handpumps are running again.</p>\n<blockquote><p>We came to save a monument. We ended up saving water.</p></blockquote>\n<p>The volunteers have written a short guide on safe desilting and are helping three other towns map their own forgotten stepwells.</p>', 15, 'The stepwell’s geometry is visible again after decades under debris.', 5, 3, 'published', 1, 0, 'embed', 'https://www.youtube.com/watch?v=aqz-KE-bpKQ', NULL, 1, 10380, 'Volunteers restored a 400-year-old stepwell in Rajasthan. Now it is full again', 'Two years of weekend work by 300 volunteers cleared tonnes of debris and brought water back to a forgotten baori.', UTC_TIMESTAMP() - INTERVAL 30 HOUR, 1, 1),
  (14, 'A grandmother’s pickle recipes became a 40-woman enterprise in the hills', 'a-grandmothers-pickle-recipes-became-a-40-woman-enterprise-in-the-hills', 'What began as jars sold to tourists is now a brand that ships across India, and keeps young women in their villages.', '<p>Kamla Devi has made the same lingad fern pickle every spring for fifty years. When her granddaughter Pooja started selling a few jars to trekkers in 2019, neither of them imagined that the recipes would one day employ forty women.</p>\n<p>Their enterprise now makes eighteen pickles and chutneys from hill produce, all sun-cured and sold online. Every recipe is credited to the woman who brought it.</p>\n<p>The best part, Pooja says, is that young women no longer have to choose between earning a living and staying home. Several have turned down offers to move to the plains.</p>', 17, 'Pickles are sun-cured on rooftops for up to three weeks.', 4, 3, 'published', 0, 0, 'none', NULL, NULL, 1, 6890, 'A grandmother’s pickle recipes became a 40-woman enterprise in the hills', 'What began as jars sold to tourists is now a brand that ships across India, and keeps young women in their villages.', UTC_TIMESTAMP() - INTERVAL 110 HOUR, 1, 1),
  (15, 'Fishermen in the Sundarbans are planting mangroves to protect their own homes', 'fishermen-in-the-sundarbans-are-planting-mangroves-to-protect-their-own-homes', 'After two cyclones in three years, a fishing community has planted 2 lakh mangrove saplings along its most exposed embankments.', '<p>The embankment behind Sabita Mondal’s house broke twice in three years. Each time, salt water ruined her family’s fields and pond. This time, the village did not wait for a new concrete wall.</p>\n<p>Over two years, families have planted roughly 2 lakh mangrove saplings along the most exposed stretches. Women run the nurseries; fishermen plant at low tide.</p>\n<p>Mangrove roots trap silt and soften waves. Older plantations nearby have already shown how much damage they can absorb, and the community hopes its young forest will do the same within a few years.</p>', 18, 'Saplings are raised in community nurseries before planting at low tide.', 2, 2, 'published', 0, 0, 'upload', NULL, 19, 1, 4760, 'Fishermen in the Sundarbans are planting mangroves to protect their own homes', 'After two cyclones in three years, a fishing community has planted 2 lakh mangrove saplings along its most exposed embankments.', UTC_TIMESTAMP() - INTERVAL 130 HOUR, 1, 1),
  (16, 'In Ladakh, solar greenhouses are bringing fresh vegetables to winter tables', 'in-ladakh-solar-greenhouses-are-bringing-fresh-vegetables-to-winter-tables', 'Walls of mud brick and a sloped polythene roof keep temperatures above freezing, even at minus 20°C outside.', '<p>Winter in Ladakh used to mean months of potatoes, dried vegetables and expensive produce trucked in before the passes close. Passive solar greenhouses are changing that.</p>\n<p>Thick mud-brick walls on three sides soak up heat during the day and release it at night. A sloped polythene roof faces south. Inside, spinach, coriander and turnips grow through January.</p>\n<p>This article is a draft in the sample data, so you can see how unpublished work appears in the admin panel.</p>', 20, 'A greenhouse uses thick mud walls to store the day’s heat.', 3, 4, 'draft', 0, 0, 'none', NULL, NULL, 1, 3640, 'In Ladakh, solar greenhouses are bringing fresh vegetables to winter tables', 'Walls of mud brick and a sloped polythene roof keep temperatures above freezing, even at minus 20°C outside.', NULL, 1, 1);



COMMIT;
